#pragma once
#include "core/portable/coresingleton.h"
#include "core/public/coreproperty.h"
#include "core/system/corethread.h"
#include "presonus/noaa/card_handler_state.hpp"
#include "presonus/noaa/sysex_receiver.hpp"
namespace Presonus::NOAA {
// Original RTTI establishes these four public bases. Modern source Thread
// replaces unavailable legacy CoreThread; native offsets/ARM ABI are unclaimed.
// Unknown original functional slots remain pure. No original lifecycle claim.
class TCardHandler : public Core::IPropertyHandler,
                     public Core::Threads::Thread,
                     public Core::Portable::Singleton<TCardHandler>,
                     public SysexReceiver {
public:
  TCardHandler(presonus::noaa::CardHandlerSetupTag,
               presonus::noaa::CardHandlerState &state,
               presonus::dice::ResponseServices &response)
      : Core::Threads::Thread("NOAA Handler source port"), state_(state) {
    setPortableResponseServices(response);
  }
  ~TCardHandler() override = default;
  void setProperty(const Core::Property &) override = 0;
  void release() override = 0;
  int threadEntry() override = 0;
  void getProperty(Core::Property &) override;
  bool accepts(const SysexPacket &) override;
  // Portable void contract; original ordinary return declaration unresolved.
  void purgeEvents();
  // Provisional source-port void return; original return declaration
  // unresolved.
  void setPropertyDeferred(const Core::Property &);
  unsigned long long getAlternateMac();
  unsigned int sendGEQBulkProperty(const Core::Property &);

private:
  presonus::noaa::CardHandlerState &state_;
};
} // namespace Presonus::NOAA

#pragma once
#include <array>
#include <atomic>
#include <cstdint>
#include <optional>
namespace Core {
struct Property;
}
namespace Presonus::NOAA {
class TCard;
class TCardRouter;
struct NOAAStatusProperty;
} // namespace Presonus::NOAA
namespace presonus::noaa {
// Explicit projections of native payload reads. Names identify observed
// offsets, not recovered original field declarations or native object layout.
struct DeferredRouteProjection {
  const Core::Property *property;
  std::uint32_t word08;
  std::int32_t count10, count18, count1c, count20;
};
struct DeferredRateProjection {
  const Core::Property *property;
  float value08;
  std::int32_t link1c;
};
// Independent borrowed bindings; no original Handler layout/ownership claim.
// Caller serializes access and keeps every bound object alive through calls.
struct CardHandlerState {
  Presonus::NOAA::TCard &card;
  // Explicit numeric projection of original Card word2c; never an opaque cast.
  std::optional<std::uint32_t> expectedSerial;
  // Required only for the matching dispatch path. Identity must match the
  // incoming Core::Property base; never reinterpret an arbitrary property.
  Presonus::NOAA::NOAAStatusProperty *statusProperty = nullptr;
  const Core::Property *geqProperty = nullptr;
  // Original bytes at offsets8..40, independent of native Property layout.
  const std::array<unsigned char, 33> *geqPayload = nullptr;
  // Borrowed source-port count; producer release-stores and consumer
  // acquire-loads. Not a claim about original +0xa4 type, ordering or native
  // object layout.
  std::atomic<std::uint32_t> *pendingEventCount = nullptr;
  Presonus::NOAA::TCardRouter *router = nullptr;
  const DeferredRouteProjection *deferredRoutes = nullptr;
  const DeferredRateProjection *deferredRate = nullptr;
};
struct CardHandlerSetupTag {};
inline constexpr CardHandlerSetupTag cardHandlerSetupTag{};
} // namespace presonus::noaa

#include "presonus/noaa/card.hpp"
#include "presonus/noaa/card_handler.hpp"
#include "presonus/noaa/router.hpp"
#include "presonus/noaa/status_property.hpp"
#include <stdexcept>
DEFINE_SINGLETON(Presonus::NOAA::TCardHandler)
namespace Presonus::NOAA {
void TCardHandler::setPropertyDeferred(const Core::Property &property) {
  // Exact native literal IDs; payloads are explicit identity-bound projections.
  if (property.type == 1936225136) {
    sendGEQBulkProperty(property);
  } else if (property.type == 1399157877) {
    if (!state_.deferredRate || state_.deferredRate->property != &property ||
        property.size != 40)
      throw std::invalid_argument(
          "NOAA Handler requires size40 rate projection");
    const auto &rate = *state_.deferredRate;
    const int code = rate.value08 < 45000.0f   ? 0
                     : rate.value08 < 49000.0f ? 1
                     : rate.value08 < 90000.0f ? 2
                                               : 3;
    state_.card.sendSampleRate(code, rate.link1c);
  } else if (property.type == 1634038640) {
    if (!state_.router || !state_.deferredRoutes ||
        state_.deferredRoutes->property != &property)
      throw std::invalid_argument(
          "NOAA Handler requires live route projection");
    auto &router = *state_.router;
    const auto &routes = *state_.deferredRoutes;
    router.initRoutes();
    auto destination = routes.word08;
    auto single = [&](std::int32_t count, unsigned char source) {
      for (std::int32_t i = 0; i < count; ++i) {
        router.setAVS48Route(static_cast<unsigned char>(destination), source, 4,
                             0);
        ++destination;
        ++source;
      }
    };
    single(routes.count10, 42);
    single(routes.count18, 56);
    auto paired = [&](std::int32_t count, unsigned char left,
                      unsigned char right) {
      for (std::int32_t i = 0; i < count; ++i) {
        router.setAVS48Route(static_cast<unsigned char>(destination), left, 4,
                             0);
        router.setAVS48Route(static_cast<unsigned char>(destination + 1u),
                             right, 4, 0);
        destination += 2u;
      }
    };
    paired(routes.count1c, 60, 61);
    paired(routes.count20, 58, 58);
  }
}
bool TCardHandler::accepts(const SysexPacket &packet) {
  return packet.length > 1 && packet.bytes[1] == 29;
}
void TCardHandler::getProperty(Core::Property &property) {
  if (property.type != NOAAStatusProperty::kID)
    return;
  if (!state_.statusProperty ||
      static_cast<Core::Property *>(state_.statusProperty) != &property)
    throw std::invalid_argument("NOAA Handler requires live status projection");
  state_.card.getStatusProperty(*state_.statusProperty);
}
unsigned long long TCardHandler::getAlternateMac() {
  if (!state_.expectedSerial)
    throw std::invalid_argument("NOAA Handler requires serial projection");
  return (10ull << 32) |
         (state_.card.generateAlternateMac(*state_.expectedSerial) |
          0x92000000u);
}
unsigned int TCardHandler::sendGEQBulkProperty(const Core::Property &property) {
  if (state_.geqProperty != &property || !state_.geqPayload)
    throw std::invalid_argument("NOAA Handler requires live GEQ projection");
  unsigned char bytes[36];
  bytes[0] = 240;
  bytes[1] = 29;
  for (unsigned i = 0; i < 33; ++i)
    bytes[i + 2] = (*state_.geqPayload)[i] & 127;
  bytes[35] = 247;
  SysexPacket packet(bytes, 36);
  post(packet);
  waitAck(500);
  return 0;
}
} // namespace Presonus::NOAA
